#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto doOp=[&](int x,int y){
        ops.push_back({x,y});
        vector<int> q(n);
        for(int i=0;i<y;i++) q[i]=p[n-y+i];
        for(int i=0;i<n-x-y;i++) q[y+i]=p[x+i];
        for(int i=0;i<x;i++) q[y+(n-x-y)+i]=p[i];
        p=q;
    };
    // Place elements n, n-1, ..., 2 from right to left
    for(int tgt=n-1;tgt>=1;tgt--){
        int pos=-1;
        for(int i=0;i<=tgt;i++) if(p[i]==tgt+1){pos=i;break;}
        if(pos==tgt) continue;
        // Move element from pos to position 0 first: x=1, y=n-1-pos if that works
        if(pos>0){
            // op x=pos, y=n-1-pos: need pos>=1, n-1-pos>=1 => pos<=n-2, and pos+(n-1-pos)=n-1<n. OK if n-1-pos>=1
            if(n-1-pos>=1) doOp(pos, n-1-pos);
            else doOp(1, n-2); // fallback
            for(int i=0;i<=tgt;i++) if(p[i]==tgt+1){pos=i;break;}
            if(pos==tgt) continue;
        }
        // pos==0 now, move to tgt
        if(tgt>=2){
            doOp(1, tgt-1); // [p[tgt-1..n-1]][p[1..tgt-2]][p[0]] -> element goes to position n-1... no to position n-1
            // Actually: result=[last tgt-1][middle=n-1-(tgt-1)=n-tgt][first 1] -> p[0] goes to pos n-1. Not tgt.
            // Use x=1, y=tgt: need 1+tgt<n. Result: [p[n-tgt..n-1]][p[1..n-tgt-1]][p[0]]. p[0] at pos n-1. Nope.
        }
        if(pos==0 && tgt<n-1 && tgt>=1) doOp(1, tgt);
        for(int i=0;i<=tgt;i++) if(p[i]==tgt+1){pos=i;break;}
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
